  ('collateral', '/kəˈlæt.ər.əl/', '担保的；附属的', 'Related to something given as security for repayment.'),
  ('interrogate', '/ɪnˈtɛrəɡeɪt/', '审问', 'To ask someone questions in a thorough or aggressive manner.'),
  ('brilliantly', '/ˈbrɪl.jəntli/', '出色地；卓越地', 'In an exceptionally bright or impressive manner.'),
  ('accessibility', '/ækˌsɛsəˈbɪləti/', '可及性', 'The quality of being easy to obtain or use.'),
  ('detach', '/dɪˈtætʃ/', '分离；脱离', 'To separate or remove something from a larger whole.'),
  ('encyclopedia', '/ɪnˌsaɪ.kləˈpiː.dɪ.ə/', '百科全书', 'A comprehensive reference work containing articles on various topics.'),
  ('delta', '/ˈdɛl.tə/', '三角洲', 'A landform at the mouth of a river where it meets a body of water.'),
  ('confound', '/kənˈfaʊnd/', '使困惑', 'To cause surprise or confusion in someone.'),
  ('reptile', '/ˈrɛp.taɪl/', '爬行动物', 'Cold-blooded vertebrates that usually lay eggs and have scales.'),
  ('commend', '/kəˈmɛnd/', '称赞；表扬', 'To express approval or admiration for someone or something.'),
  ('neutralize', '/ˈnjuː.trə.laɪz/', '中和；抵消', 'To counteract or balance the effect of something.'),
  ('confiscate', '/ˈkɒn.fɪ.s.keɪt/', '没收', 'To take something away from someone, especially as a penalty.'),
  ('reciprocal', '/rɪˈsɪprəkl/', '相互的；互惠的', 'Mutual or corresponding in action, influence, or relationship.'),
  ('emigrate', '/ˈɛm.ɪ.ɡreɪt/', '移民', 'To leave one''s country to settle in another.'),
  ('individualism', '/ˌɪndɪˈvɪdʒuəlɪzəm/', '个人主义', 'A social theory advocating the moral worth of the individual.')
  ) AS v(headword, ipa, def_zh, def_en)
 WHERE lower(w.headword) = v.headword;

INSERT INTO vocab_examples (word_id, sort_order, collocation, sentence, translation_zh, scene)
SELECT w.id, v.sort_order, v.collocation, v.sentence, v.translation_zh, v.scene
  FROM (VALUES
  ('stash', 1, 'stash away', 'People often stash away money for emergencies when they budget their expenses.', '人们在制定预算时，常常会把钱存起来以备急用。', 'daily_life'),
  ('stash', 2, 'stash of cash', 'Authorities discovered a large stash of cash hidden in the suspect''s residence during the investigation.', '当局在调查过程中，在嫌疑人的住所发现了大量隐藏的现金。', 'news'),
  ('stash', 3, 'stash items', 'Students tend to stash items in their backpacks to keep their desks organized and tidy.', '学生们往往会把物品藏在书包里，以保持书桌整洁有序。', 'education'),
  ('generalize', 1, 'generalize findings', 'Researchers often generalize findings to apply them to broader contexts in their studies.', '研究人员经常将研究结果概括，以便将其应用于更广泛的背景中。', 'academic'),
  ('generalize', 2, 'generalize trends', 'Experts argue that we should not generalize trends from limited data sets during economic reports.', '专家们认为，在经济报告中，我们不应根据有限的数据集来概括趋势。', 'news'),
  ('generalize', 3, 'generalize rules', 'Teachers should be cautious when they generalize rules based on a few student behaviors.', '教师在根据少数学生的行为概括规则时应保持谨慎。', 'education'),
  ('arid', 1, 'arid climate', 'Deserts are often characterized by an arid climate with minimal rainfall throughout the year.', '沙漠通常具有干旱的气候，全年降水量极少。', 'environment'),
  ('arid', 2, 'arid region', 'Travelers should prepare for extreme conditions when visiting an arid region, especially during summer.', '游客在访问干旱地区时，应为极端天气做好准备，特别是在夏季。', 'travel'),
  ('arid', 3, 'arid landscape', 'Artists frequently depict the beauty of an arid landscape in their paintings, highlighting the unique colors.', '艺术家们常常在画作中描绘干旱景观的美，突出独特的色彩。', 'culture'),
  ('patriarch', 1, 'family patriarch', 'Many cultures still honor the role of the family patriarch in decision-making.', '许多文化仍然尊重家长在决策中的角色。', 'daily_life'),
  ('patriarch', 2, 'tribal patriarch', 'In indigenous societies, the tribal patriarch often leads important ceremonies and gatherings.', '在土著社会中，部落家长通常主持重要的仪式和聚会。', 'culture'),
  ('patriarch', 3, 'religious patriarch', 'The religious patriarch addressed the congregation during the annual celebration of faith.', '宗教家长在年度信仰庆典上向会众发表讲话。', 'education'),
  ('transient', 1, 'transient population', 'Cities often experience a transient population due to tourism and migration trends.', '由于旅游和迁徙趋势，城市通常会经历短暂的人口变化。', 'culture'),
  ('transient', 2, 'transient nature', 'The transient nature of certain materials makes them ideal for temporary applications in engineering.', '某些材料的短暂特性使它们在工程中的临时应用变得理想。', 'science_tech'),
  ('transient', 3, 'transient effects', 'Research shows that transient effects of stress can impact overall health when experienced frequently.', '研究表明，频繁经历的短暂压力会影响整体健康。', 'health'),
  ('loot', 1, 'loot the bank', 'Authorities reported that the gang planned to loot the bank during the night.', '当局报告称，该团伙计划在夜间劫掠银行。', 'news'),
  ('loot', 2, 'loot from soldiers', 'Local residents discovered loot from soldiers hidden in the forest after the battle.', '当地居民在战斗后发现藏在森林中的士兵的战利品。', 'culture'),
  ('loot', 3, 'loot boxes', 'Many gamers enjoy opening loot boxes for rare items in video games.', '许多玩家喜欢打开战利品箱以获取视频游戏中的稀有物品。', 'daily_life'),
  ('propulsion', 1, 'rocket propulsion', 'Engineers are exploring new technologies for rocket propulsion to improve space travel efficiency.', '工程师正在探索火箭推进的新技术，以提高太空旅行的效率。', 'science_tech'),
  ('propulsion', 2, 'jet propulsion', 'Jet propulsion systems are revolutionizing the way we think about air travel.', '喷气推进系统正在革新我们对航空旅行的思考。', 'daily_life'),
  ('propulsion', 3, 'marine propulsion', 'Innovations in marine propulsion are essential for reducing pollution in our oceans.', '海洋推进技术的创新对减少海洋污染至关重要。', 'environment'),
  ('legalize', 1, 'legalize marijuana', 'Many states in the US have chosen to legalize marijuana for recreational use.', '美国许多州已选择合法化娱乐用途的大麻。', 'news'),
  ('legalize', 2, 'legalize same-sex marriage', 'Activists are working tirelessly to legalize same-sex marriage in more countries worldwide.', '活动家们正在不懈努力，以在更多国家合法化同性婚姻。', 'culture'),
  ('legalize', 3, 'legalize gambling', 'Some politicians believe that legalizing gambling could boost the local economy significantly.', '一些政治家认为，合法化赌博可以显著促进当地经济。', 'daily_life'),
  ('caricature', 1, 'political caricature', 'Artists often create political caricatures to comment on current events and societal issues.', '艺术家们经常创作政治漫画，以评论当前事件和社会问题。', 'culture'),
  ('caricature', 2, 'caricature of a celebrity', 'The magazine featured a caricature of a celebrity on its cover to attract readers'' attention.', '这本杂志在封面上展示了一个名人的漫画，以吸引读者的注意。', 'news'),
  ('caricature', 3, 'caricature style', 'Many children enjoy drawing in caricature style, making their friends look funny and exaggerated.', '许多孩子喜欢以漫画风格绘画，让他们的朋友看起来搞笑而夸张。', 'daily_life'),
  ('attire', 1, 'formal attire', 'Guests were required to wear formal attire for the gala event tonight.', '今晚，嘉宾必须穿着正式的服装参加晚会。', 'culture'),
  ('attire', 2, 'traditional attire', 'Many tourists enjoy wearing traditional attire during cultural festivals in various countries.', '许多游客在各国的文化节庆中喜欢穿着传统服装。', 'travel'),
  ('attire', 3, 'casual attire', 'He prefers to wear casual attire when going out with friends on weekends.', '他周末和朋友出门时喜欢穿着休闲服装。', 'daily_life'),
  ('derivative', 1, 'derivative work', 'Scholars often create derivative works based on previous research findings to advance knowledge.', '学者们常常基于先前的研究成果创作派生作品，以推动知识进步。', 'academic'),
  ('derivative', 2, 'derivative product', 'Companies frequently develop derivative products to meet changing market demands and customer preferences.', '公司们经常开发派生产品，以满足不断变化的市场需求和客户偏好。', 'work'),
  ('derivative', 3, 'derivative formula', 'Researchers have proposed a derivative formula to improve the accuracy of climate models in recent studies.', '研究人员在最近的研究中提出了一种派生公式，以提高气候模型的准确性。', 'science_tech'),
  ('splendor', 1, 'natural splendor', 'Visitors were mesmerized by the natural splendor of the national park during their trip.', '游客在旅行中被国家公园的自然辉煌所迷住。', 'travel'),
  ('splendor', 2, 'splendor of the ceremony', 'Everyone admired the splendor of the ceremony as the performers showcased their talents.', '每个人都赞叹仪式的辉煌，表演者们展示了他们的才华。', 'culture'),
  ('splendor', 3, 'historic splendor', 'Students studied the historic splendor of ancient civilizations to understand their cultural significance.', '学生们研究古代文明的历史辉煌，以理解它们的文化重要性。', 'education'),
  ('informative', 1, 'informative article', 'Readers found the article to be particularly informative regarding recent policy changes.', '读者发现这篇文章在最近的政策变化方面尤其具有启发性。', 'news'),
  ('informative', 2, 'informative presentation', 'She delivered an informative presentation that engaged all the attendees during the seminar.', '她在研讨会上进行了一个吸引所有与会者的有启发性的演讲。', 'education'),
  ('informative', 3, 'informative session', 'The team held an informative session to update everyone on the new project guidelines.', '团队举行了一次有启发性的会议，以更新每个人关于新项目的指导方针。', 'work'),
  ('funnel', 1, 'funnel cake', 'People often eat funnel cake at fairs and carnivals, enjoying its sweet taste.', '人们常在集市和嘉年华上吃漏斗饼，享受它的甜味。', 'daily_life'),
  ('funnel', 2, 'data funnel', 'Marketers analyze the data funnel to improve customer engagement and conversion rates.', '营销人员分析数据漏斗，以提高客户参与度和转化率。', 'science_tech'),
  ('funnel', 3, 'sales funnel', 'Understanding the sales funnel is essential for maximizing revenue and closing deals.', '理解销售漏斗对于最大化收入和达成交易至关重要。', 'work'),
