  ('viability', 2, 'scientific viability', 'Researchers are evaluating the scientific viability of the proposed solutions to climate change.', '研究人员正在评估所提出的应对气候变化的科学可行性。', 'science_tech'),
  ('viability', 3, 'long-term viability', 'The long-term viability of the wetlands depends on pollution control measures being implemented.', '湿地的长期可行性取决于污染控制措施的实施。', 'environment'),
  ('cohesion', 1, 'cohesion between ideas', 'Effective writing requires cohesion between ideas to guide the reader through complex arguments.', '有效的写作需要不同思想之间的凝聚，以引导读者理解复杂的论点。', 'academic'),
  ('cohesion', 2, 'social cohesion', 'Communities thrive when there is social cohesion, fostering trust and cooperation among members.', '当社会凝聚力强时，社区蓬勃发展，促进成员之间的信任与合作。', 'culture'),
