  ('emigrate', 1, 'emigrate to another country', 'Many people choose to emigrate to another country for better opportunities.', '许多人选择移民到其他国家以寻求更好的机会。', 'daily_life'),
  ('emigrate', 2, 'emigrate for work', 'Some professionals decide to emigrate for work in a more developed economy.', '一些专业人士决定移民到更发达的经济体工作。', 'work'),
  ('emigrate', 3, 'emigrate due to conflict', 'Thousands have had to emigrate due to conflict and persecution in their homeland.', '数千人因故乡的冲突和迫害而不得不移民。', 'news'),
  ('individualism', 1, 'individualism and collectivism', 'Cultural debates often center around individualism and collectivism in modern societies.', '文化辩论常围绕现代社会的个人主义和集体主义展开。', 'culture'),
  ('individualism', 2, 'individualism in education', 'Teachers must find a balance between individualism in education and collaborative learning experiences.', '教师必须在教育中的个人主义和合作学习经历之间找到平衡。', 'education'),
